    int status;
} Person;

int main() {
    // Allocate memory for a new person
    Person *newPerson = (Person *)malloc(sizeof(Person));

    if (newPerson == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Set the fields of the newly allocated person
    newPerson->id = 1;       // Example ID
    snprintf(newPerson->name, sizeof(newPerson->name), "John Doe"); // Example name
    newPerson->status = 0;   // Setting status to 0 as specified

    // Print out the details of the person
    printf("Person Details:\n");
    printf("ID: %d\n", newPerson->id);
    printf("Name: %s\n", newPerson->name);
    printf("Status: %d\n", newPerson->status);

    // Free the allocated memory
    free(newPerson);

    return 0;
}
```

### Explanation:
- **Struct Definition**: A `struct` named `Person` is defined with three members: an integer `id`, a character array `name`, and another integer `status`.

- **Memory Allocation**: The `malloc()` function is used to allocate memory for one instance of the `Person` struct. We check if the allocation was successful by verifying that `newPerson` is not `NULL`.

- **Setting Values**: Using the `->` operator, we access and set the fields (`id`, `name`, and `status`) of the `Person` structure.

- **Output**: The program prints out the details of the person to verify that they have been correctly set.

- **Memory Deallocation**: Finally, the allocated memory is freed using `free(newPerson)` to avoid memory leaks.']

