['Below is the C code that fulfills the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to trim trailing whitespace from a string
char* trim_trailing_whitespace(char *str) {
    if (str == NULL) return str;

    // Find the end of the last non-whitespace character
    char *end = str + strlen(str) - 1;

    while (end >= str && (*end == ' ' || *end == '\t' || *end == '\n')) {
        --end;
    }

    // Null-terminate the string at the end of the last non-whitespace character
    *(end + 1) = '\0';

    return str;
}

int main(int argc, char *argv[]) {
    if (argc != 2) { // Check if exactly one argument is provided
        fprintf(stderr, "Error: Exactly one argument expected.\n");
        exit(EXIT_FAILURE);
    }

    char *input = argv[1]; // Get the argument from the command line

    printf("Argument: %s\n", input); // Print the argument

    trim_trailing_whitespace(input); // Trim trailing whitespace

    printf("Trimmed Argument: %s\n", input); // Print the trimmed argument again

    exit(EXIT_SUCCESS); // Exit the program
}
```

### Explanation:

1. **Include Headers**: 
   - `<stdio.h>` for standard input/output functions.
   - `<stdlib.h>` for `exit()` function and other utilities.
   - `<string.h>` for string manipulation functions.

2. **`trim_trailing_whitespace` Function**:
