['To implement the `http_hello_page` function in C, we need to handle basic file I/O operations and string manipulation. This example assumes that the request file stream contains an HTTP GET request with a query parameter for the username (e.g., `GET /?username=John`). We will read this request, extract the username, and construct an appropriate HTTP response.

Here's how you can implement it:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to extract username from query parameter in the request line
char* get_username_from_request(const char *request_line) {
    const char *query_start = strstr(request_line, "?username=");
    if (!query_start || strlen(query_start) <= 9) {
        return NULL;
    }

    // Username starts after '?username=' and ends at space or newline
    const char *username_start = query_start + 9;
    size_t username_length = strcspn(username_start, " \r\n");
    char *username = (char *)malloc((username_length + 1) * sizeof(char));

    if (!username) {
        return NULL; // Memory allocation failed
    }

    strncpy(username, username_start, username_length);
    username[username_length] = '\0'; // Null-terminate the string

    return username;
}

void http_hello_page(FILE *request_stream, FILE *response_stream) {
    char request_line[512];  // Buffer to hold a line from the request

    if (fgets(request_line, sizeof(request_line), request_stream) == NULL) {
        fprintf(stderr, "Failed to read request line\n");
        return;
    }

    const char *username = get_username_from_request(request_line);

    if (!username) {
        fprintf(stderr, "Username not found in the request\n");

        // Respond with a 400 Bad Request
        fprintf(response_stream,
                "HTTP/1.1 400 Bad Request\r\n"
                "Content-Type: text/plain\r\n"
                "\r\n"
                "Bad Request: Username not provided.\n");
    } else {
        // Construct and send the response
        fprintf(response_stream,
                "HTTP/1.1 200 OK\r\n"
                "Content-Type: text/html\r\n"
                "\r\n"
                "<html><body>"
                "<h1>Hello %s</h1>"
                "</body></html>\n", username);
    }

    // Clean up
    free((void *)username);  // Free the allocated memory for username
}

int main() {
    // Example usage
    FILE *request = fopen("request.txt", "r");
    if (!request) {
        perror("Failed to open request file");
        return EXIT_FAILURE;
    }

    FILE *response = fopen("response.html", "w");
    if (!response) {
        perror("Failed to open response file");
        fclose(request);
        return EXIT_FAILURE;
    }

    http_hello_page(request, response);

    // Close files
    fclose(request);
    fclose(response);

    return EXIT_SUCCESS;
}
```

### Explanation:
1. **Reading the Request**: The function `http_hello_page` reads a line from the request file stream using `fgets`. This line should contain the HTTP GET request.

2. **Extracting Username**: The helper function `get_username_from_request` searches for the query parameter `?username=` in the request line and extracts the username value. It handles memory allocation and ensures the string is null-terminated.

3. **Constructing Response**:
   - If a username is found, it constructs an HTTP response with status 200 OK and includes the greeting "Hello [username]".
   - If no username is found, it returns a 400 Bad Request error with a message indicating that the username was not provided.

4. **Memory Management**: The code ensures any dynamically allocated memory for the username is freed after use to prevent memory leaks.

5. **Example Usage**: The `main` function demonstrates how to use `http_hello_page`, reading from a file named `request.txt` and writing to `response.html`. You can test this with appropriate content in `request.txt`.

Ensure that you have proper error handling for real-world applications, especially when dealing with network I/O.']

['Below is an implementation of the `http_hello_page` function in C, along with a basic version of the `escape_html` function. This example assumes you're using POSIX file streams and standard I/O for simplicity.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to escape HTML special characters
void escape_html(const char *input, char *output) {
    if (input == NULL || output == NULL) return;

    while (*input != '\0') {
        switch (*input) {
            case '&': strcat(output, "&amp;"); break;
            case '<': strcat(output, "&lt;"); break;
            case '>': strcat(output, "&gt;"); break;
            case '"': strcat(output, "&quot;"); break;
            case '\'': strcat(output, "&#39;"); break;
            default: strncat(output, input, 1); break;
        }
        input++;
    }
}

// Function to extract the username from the request
char* extract_username(FILE *request) {
    if (request == NULL) return NULL;

    char buffer[1024];
    char *username = NULL;

    // Read the request line by line
    while (fgets(buffer, sizeof(buffer), request)) {
        // Look for a "GET /?username=..." pattern in the request
        if (strncmp(buffer, "GET /?", 5) == 0 && strstr(buffer, "username=") != NULL) {
            char *start = strstr(buffer, "username=");
            if (start) {
                start += strlen("username="); // Move to the beginning of username
                char *end = strchr(start, ' '); // Look for end of parameter or request
                if (!end) end = strchr(start, '\n'); // Use newline if space is not found

                size_t len = end - start;
                if (len > 0) {
                    username = malloc(len + 1);
                    strncpy(username, start, len);
                    username[len] = '\0';
                }
            }
        }
    }

    return username; // Caller should free this memory
}

// Function to construct the HTTP response with "hello [username]"
void http_hello_page(FILE *request, FILE *response) {
    if (request == NULL || response == NULL) return;

    char *username = extract_username(request);
    if (username == NULL) {
        // Default message if no username is found
        fprintf(response, "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n");
        fprintf(response, "<html><body><h1>hello guest</h1></body></html>\r\n");
    } else {
        // Create the response with escaped username
        char safe_username[1024];
        escape_html(username, safe_username);

        fprintf(response, "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n");
        fprintf(response, "<html><body><h1>hello %s</h1></body></html>\r\n", safe_username);

        free(username); // Free the allocated memory for username
    }
}

int main() {
    // Example usage:
    FILE *request = fopen("request.txt", "r");
    if (request == NULL) {
        perror("Failed to open request file");
        return EXIT_FAILURE;
    }

    FILE *response = fopen("response.txt", "w");
    if (response == NULL) {
        fclose(request);
        perror("Failed to open response file");
        return EXIT_FAILURE;
    }

    http_hello_page(request, response);

    fclose(request);
    fclose(response);
    return 0;
}
```

### Key Points:
1. **HTML Escaping**: The `escape_html` function takes care of escaping HTML special characters in the username.
2. **Request Parsing**: This example assumes a simple GET request format where the username is passed as a query parameter (`username=`).
3. **Memory Management**: Ensure to free any allocated memory for the username after use.
4. **Error Handling**: Basic error handling ensures that files are properly checked and managed.

You might need to adjust buffer sizes or parsing logic depending on your actual request format.']

