### Step 1: Check Email Existence in Database

Assuming you have a database (like MySQL) with an `emails` table, you can use Python to check if the email exists.

```python
import mysql.connector

def email_exists(email):
    try:
        # Connect to your database
        connection = mysql.connector.connect(
            host='your_host',
            user='your_user',
            password='your_password',
            database='your_database'
        )

        cursor = connection.cursor()

        # Query to check if the email exists
        query = "SELECT COUNT(*) FROM emails WHERE email_address = %s"
        cursor.execute(query, (email,))

        result = cursor.fetchone()[0]
        return result > 0

    except mysql.connector.Error as err:
        print(f"Error: {err}")
        return False
    finally:
        if connection.is_connected():
            cursor.close()
            connection.close()

def unsubscribe_email(email):
    import subprocess

    # Call the PHP script to unsubscribe the email
    try:
        result = subprocess.run(
            ['php', 'unsubscribe.php', email],
            capture_output=True,
            text=True,
            check=True
        )

        # Check the output of the PHP script
        if result.stdout.strip() == '0':
            return 1
        else:
            return 0

    except subprocess.CalledProcessError as e:
        print(f"PHP script error: {e}")
        return 0

def main(email):
    if email_exists(email):
        return unsubscribe_email(email)
    else:
        return 0

# Example usage
email_to_check = 'example@example.com'
result = main(email_to_check)
print(result)  # Output will be 1 or 0 based on the conditions described
```

