$query->bind_param('s', $email);

if ($query->execute()) {
    if ($query->affected_rows > 0) {
        echo "0"; // Success
    } else {
        echo "1"; // No rows affected (error)
    }
} else {
    echo "1"; // Execution error
}

$query->close();
$mysqli->close();
?>
